-- High West (highwest.com + ship.highwest.com, the maker's own Shopify store): 8 corrections/confirmations,
-- 7 additions (every one states its proof), 2 release-as-row merges, 6 seed rows with no current label
-- flagged discontinued. Generated by scripts/bourbon_write.py from catalog/sources/bourbon/high_west.py;
-- every UPDATE is guarded `facts_verified_at is null`. Maker row 802cf349... already existed (no website/country).
-- Maker image addresses go to specs->source_image_url, never image_url.

update cellar.makers set website = coalesce(website, 'https://highwest.com'), country = coalesce(country, 'US') where id = '802cf349-2a60-458f-8258-dfb2fbf1ae89';

-- corrections, confirmations, discontinued (Rocky Mountain Rye 16/21, Son of Bourye, 14 Year Light, Double Rye Campfire/Manhattan Finish:
-- not on highwest.com/pages/product-information, the compliance list of every current label, nor on any limited-release page)
update cellar.products set age_label = '10+ yr', nas = false, spirit_type = 'blend', producer = coalesce(producer, 'High West'), producer_id = coalesce(producer_id, '802cf349-2a60-458f-8258-dfb2fbf1ae89'::uuid), source = 'maker', source_url = 'https://highwest.com/pages/limited-releases', source_checked_at = now(), discontinued = false, catalog_included = catalog_included or is_core_range where id = '59270713-bbf2-4dad-a83e-cf40cf5ab976' and facts_verified_at is null;
