est Bottled in Bond Bourbon","rar":"allocated","f":"High West","x":"Bottled in Bond Bourbon","p":100.0,"ay":4.4,"al":"4 yr 5 mo","nas":false,"et":"standard","ms":"high_rye","mb":null,"st":"bourbon","bib":true,"bp":false,"fin":null,"msrp":null,"core":false,"al2":[],"img":null,"u":"https://highwest.com/pages/limited-releases","pr":"High West","mk":"802cf349-2a60-458f-8258-dfb2fbf1ae89"},{"n":"High West Bottled in Bond Rye","rar":"allocated","f":"High West","x":"Bottled in Bond Rye","p":100.0,"ay":null,"al":null,"nas":false,"et":"standard","ms":"rye","mb":"80% rye, 20% malted rye","st":"rye","bib":true,"bp":false,"fin":null,"msrp":null,"core":true,"al2":["High West Bonded Rye"],"img":"https://ship.highwest.com/cdn/shop/files/1_ecde9705-302d-4efc-9dcd-50d49cd1ffc7.png","u":"https://ship.highwest.com/products/bottled-in-bond-rye","pr":"High West","mk":"802cf349-2a60-458f-8258-dfb2fbf1ae89"}]$j$::jsonb) as r(n text, f text, x text, p numeric, ay numeric, al text, nas bool, et text, ms text, mb text, st text, bib bool, bp bool, fin text, msrp numeric, core bool, al2 text[], img text, u text, pr text, mk text, rar text)
where not exists (select 1 from cellar.products e where e.type = 'bourbon' and e.merged_into is null and coalesce(e.brand_family, '') = coalesce(r.f, '') and coalesce(e.expression, '') = coalesce(r.x, '') and coalesce(e.release_label, '') = '');
